$('#startBtn').onclick=()=>{load();refreshVisible();show('quiz');renderQuestion()}; $('#nextBtn').onclick=next;$('#backBtn').onclick=back;
$('#restartBtn').onclick=()=>{if(confirm('Vuoi ricominciare l’assessment?')){localStorage.removeItem('scs-ai-cost-assessment');state.answers={};state.index=0;refreshVisible();show('quiz');renderQuestion();}};
$('#copyBtn').onclick=async()=>{try{await navigator.clipboard.writeText(summaryText());toast('Sintesi copiata')}catch(e){toast('Copia non disponibile su questo browser')}};$('#printBtn').onclick=()=>window.print();
document.addEventListener('keydown',e=>{if($('#quiz').classList.contains('active')&&e.key==='Enter'&&!e.shiftKey){const tag=document.activeElement?.tagName;if(tag!=='BUTTON'){e.preventDefault();next()}}});
// subtle network background
const canvas=$('#mesh'),ctx=canvas.getContext('2d');let pts=[],raf;function resize(){const d=Math.min(devicePixelRatio||1,2);canvas.width=innerWidth*d;canvas.height=innerHeight*d;ctx.setTransform(d,0,0,d,0,0);pts=Array.from({length:Math.min(52,Math.max(22,Math.floor(innerWidth/28)))},()=>({x:Math.random()*innerWidth,y:Math.random()*innerHeight,vx:(Math.random()-.5)*.16,vy:(Math.random()-.5)*.16,r:Math.random()*1.3+.4}))}
function draw(){ctx.clearRect(0,0,innerWidth,innerHeight);for(const p of pts){p.x+=p.vx;p.y+=p.vy;if(p.x<0||p.x>innerWidth)p.vx*=-1;if(p.y<0||p.y>innerHeight)p.vy*=-1}for(let i=0;i<pts.length;i++){for(let j=i+1;j<pts.length;j++){const a=pts[i],b=pts[j],dx=a.x-b.x,dy=a.y-b.y,d=Math.hypot(dx,dy);if(d<140){ctx.strokeStyle=`rgba(105,177,194,${(1-d/140)*.075})`;ctx.lineWidth=.6;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke()}}}for(const p of pts){ctx.fillStyle='rgba(203,227,235,.23)';ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill()}raf=requestAnimationFrame(draw)}
if(!matchMedia('(prefers-reduced-motion: reduce)').matches){resize();draw();addEventListener('resize',()=>{cancelAnimationFrame(raf);resize();draw()})}
